import unittest

from tokenauth.keys import is_valid, make_key


class TestKeys(unittest.TestCase):
    def test_well_formed_key_accepted(self):
        # keys generated by make_key must validate (BUG: currently rejected)
        key = make_key("01234567")
        self.assertTrue(is_valid(key))

    def test_bad_checksum_rejected(self):
        key = make_key("01234567")
        bad = key[:-1] + ("0" if key[-1] != "0" else "1")
        self.assertFalse(is_valid(bad))

    def test_malformed_rejected(self):
        for t in ["", "sb_", "SB_012345670", "sb_01234567zz", "xx_012345670"]:
            self.assertFalse(is_valid(t))

    def test_none_safe(self):
        # BUG: currently raises TypeError
        self.assertFalse(is_valid(None))


if __name__ == "__main__":
    unittest.main()
